ask(1870,'navigation-commands','Navigation launch arguments, linked mapping and pose workflow','A supplied configuration audit finds: model value waffle.; map argument path/to/my_map.yaml although the actual file is /maps/lab.yaml; and navigation using wall time while all sensors use simulation time. Which repair set addresses all three stated faults?', [('Use waffle, point map to /maps/lab.yaml, and configure navigation for the same simulation clock','These repairs address model selection, map resolution and timestamp consistency together.'),('Use waffle and /maps/lab.yaml, but retain wall time because the map is static','Static map geometry does not make sensor and transform timestamps independent of clock consistency.'),('Keep waffle. and the placeholder, but repeatedly resend the RViz goal','Resending a goal does not fix configuration inputs.')],kind='synthesis',difficulty='medium',ck='code',ass=['All three faults explicitly supplied; correct YAML/image exist; simulator and sensor clocks are already configured; no command executed.'],steps=['Repair the literal model-name punctuation.','Replace the map placeholder with the actual YAML path.','Align navigation with the simulated sensor/transform time source before sending the goal.'],cites=[(1867,'code','Model export line'),(1868,'code','use_sim_time:=True mapping argument')],conflict=PH,primary=[TB,SLAM])
ask(1866,'navigation-workflow','End-to-end map-based navigation, linked roles and status panels','A valid map is loaded, AMCL is active, and a valid goal is sent. A new obstacle blocks the planned route; the controller reports failure. Under a supplied policy to recover once, replan once, then report failure if no feasible path exists, which outcome is correct?', [('Invoke the permitted recovery/replan sequence, then report failure if the route remains infeasible','The workflow combines task coordination, current obstacle handling and honest goal status.'),('Report reached immediately because localization is active','Localization readiness is not goal completion.'),('Erase the obstacle from the static map without new evidence and report reached','Changing map evidence to satisfy a goal is not the supplied failure policy.')],kind='synthesis',difficulty='medium',ass=['This recovery-count policy is supplied, not an exact Nav2 default tree; no collision-free path after the retry; no physical movement is executed.'],steps=['Use the controller failure to trigger the supplied recovery action.','Replan once using the updated environmental representation.','If no feasible path exists, report navigation failure rather than reached.'],cites=[(1860,'statement','Recovery and replanning tasks'),(1862,'statement','Controller sensor/state inputs'),(1873,'figure','Reached feedback is a goal status, not merely active localization')])
